public class Main {
    public static void main(String[] args) {
        int n = 5, count = 0;
        for (int i = 0; i < n; i++) {
            for (int j = i; j < n; j++) {
                count++;
            }
        }
        System.out.println(count);
    }
}

public class Main {
    public static void main(String[] args) {
        int i = 1, count = 0;
        while (i < 100) {
            i *= 2;
            count++;
        }
        System.out.println(count);
        System.out.println(i);
    }
}
